// 관리 서비스 코드 → 이름 (제품명은 그대로, 번역이 필요한 셋은 I18N 의 m.* 키)
const MANAGER_NAMES = {
  "autoscaling": "Auto Scaling", "karpenter": "Karpenter", "beanstalk": "Elastic Beanstalk", "spot-fleet": "Spot Fleet",
  "ec2-fleet": "EC2 Fleet", "emr": "EMR", "eks": "EKS", "cloud9": "Cloud9", "cloudformation": "CloudFormation", "kubernetes": "Kubernetes",
};

function detectLang() {
  let saved = null;
  try { saved = localStorage.getItem("lang"); } catch {}
  if (saved && I18N[saved]) return saved;
  const nav = (navigator.language || "en").toLowerCase();
  if (nav.startsWith("zh")) return /tw|hk|mo|hant/.test(nav) ? "zh-TW" : "zh-CN";
  const base = nav.split("-")[0];
  return I18N[base] ? base : "en";
}
let LANG = detectLang();

function t(key, p = {}) {
  const s = I18N[LANG]?.[key] ?? I18N.en[key] ?? key;
  return s.replace(/\{(\w+)\}/g, (_, k) => (p[k] ?? ""));
}
const regionName = (code) => REGION_NAMES[LANG]?.[code] ?? REGION_NAMES.en[code] ?? code;
const managerName = (code) => I18N[LANG]?.["m." + code] ?? I18N.en["m." + code] ?? MANAGER_NAMES[code] ?? code;

// 서버 오류 {error: 코드, params} → 문장
function errText(j) {
  if (!j || !j.error) return "";
  return t("err." + j.error, j.params || {});
}

// HTML 의 data-i18n / data-i18n-title / data-i18n-ph 를 지금 언어로
function applyStaticText(root = document) {
  root.querySelectorAll("[data-i18n]").forEach(el => { el.textContent = t(el.dataset.i18n); });
  root.querySelectorAll("[data-i18n-title]").forEach(el => { el.title = t(el.dataset.i18nTitle); });
  root.querySelectorAll("[data-i18n-ph]").forEach(el => { el.placeholder = t(el.dataset.i18nPh); });
  document.documentElement.lang = LANG;
}
